#!/usr/bin/env python3
"""Embed the same fictional CSV used by Android, without a runtime sample path."""
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def generate():
    content = (ROOT / 'samples/synthetic-patients-50-expanded.csv').read_bytes()
    text = content.decode('utf-8-sig')
    output = ROOT / 'desktop/desktop_demo_sample.py'
    output.write_text(
        '"""Generated by samples/generate_desktop_demo.py; fictional data only."""\n'
        '# SHA-256: ' + hashlib.sha256(content).hexdigest() + '\n'
        'from functools import lru_cache\n\n\n@lru_cache(maxsize=1)\n'
        'def sample_shift():\n'
        '    from desktop_protocol_common import BUNDLE\n'
        '    from desktop_wire import parse_bundle\n'
        '    return parse_bundle((BUNDLE + "\\n" + CSV).encode("utf-8"))[0]\n\n\n'
        'CSV = ' + repr(text) + '\n', encoding='utf-8')


if __name__ == '__main__':
    generate()
